export type Invoice = { id: string; name: string; amount: number }

export type DashboardData = {
  totalRevenue: number
  totalInvoices: number
  revenue: { month: string; amount: number }[]
  invoices: Invoice[]
}

// Uncached fetch: stays dynamic and streams at request time. Next.js memoizes
// fetch per request, so the three sections below share a single network call.
export async function getDashboardData(): Promise<DashboardData> {
  const res = await fetch('https://api.example.com/dashboard')
  return res.json()
}

