import { Suspense } from 'react'
import { RevenueChart, RevenueChartSection, RevenueChartSkeleton } from './RevenueChart'
import {
  LatestInvoices,
  LatestInvoicesSection,
  LatestInvoicesSkeleton,
} from './LatestInvoices'
import { CardStats, CardStatsSection, CardStatsSkeleton } from './CardStats'

// Synchronous page component: its chrome (the <h1> and each section's heading,
// supplied via the Suspense fallbacks) is prerendered into the static shell and
// served instantly. Each section's uncached data fetch lives below its own
// <Suspense> boundary and streams in at request time.
export default function Page() {
  return (
    <main>
      <h1>Dashboard</h1>
      <Suspense fallback={<CardStatsSkeleton />}>
        <CardStatsSection />
      </Suspense>
      <Suspense fallback={<RevenueChartSkeleton />}>
        <RevenueChartSection />
      </Suspense>
      <Suspense fallback={<LatestInvoicesSkeleton />}>
        <LatestInvoicesSection />
      </Suspense>
    </main>
  )
}

